function anonCase(p){
 const c=JSON.parse(JSON.stringify(p)); delete c.sample;
 if(document.getElementById('anonChk').checked){
  c.initials=''; ['startDate','deathDate','lastFU'].forEach(k=>c[k]='');
  c.lines.forEach(l=>{l.start='';l.end='';}); c.events.forEach(e=>e.date='');
 }
 c.id=uid(); return c;
}
